package cli

import (
	"fmt"
	"strings"

	"github.com/insajin/autopus-adk/pkg/adapter"
	"github.com/insajin/autopus-adk/pkg/version"
)

// stickyBinaryVersion is the running auto version; tests replace it.
var stickyBinaryVersion = version.Version

// stickyStaleSurfaceAlert returns a one-paragraph alert when the installed
// Claude Code surface was generated by a different auto version than the one
// running this hook, or "" when they match or the comparison means nothing.
//
// It reads one small manifest file, so it fits the per-prompt hook budget that
// a full drift regeneration (auto doctor) does not. A session started on a
// stale surface follows rules the current release has replaced, and nothing
// else tells it so until someone runs auto doctor by hand.
func stickyStaleSurfaceAlert(root string) string {
	running := stickyBinaryVersion()
	if !isReleaseVersion(running) {
		return ""
	}
	m, err := adapter.LoadManifest(root, "claude-code")
	if err != nil || m == nil || m.Generator == running {
		return ""
	}
	generator := "an older auto"
	if m.Generator != "" {
		generator = "auto " + m.Generator
	}
	return fmt.Sprintf("Harness alert: the installed rules and skills were generated by %s, but this project now runs auto %s. "+
		"The installed instructions may be out of date: tell the user and suggest `auto update` before relying on them.",
		generator, running)
}

// isReleaseVersion reports whether v names a published build. Local and dirty
// builds change on every compile, so comparing them would alert constantly.
func isReleaseVersion(v string) bool {
	if v == "" || v == "dev" || v == "unknown" {
		return false
	}
	return !strings.Contains(v, "dirty") && !strings.Contains(v, "devel")
}

// joinStickyAlerts joins the non-empty alerts with a blank line.
func joinStickyAlerts(alerts ...string) string {
	kept := alerts[:0:0]
	for _, a := range alerts {
		if a != "" {
			kept = append(kept, a)
		}
	}
	return strings.Join(kept, "\n\n")
}
